package engine

import (
	"context"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/lair-sh/lair/internal/config"
	"github.com/lair-sh/lair/internal/php"
)

// DebuggerRequest is the wire payload of the `debugger` daemon action. The
// toggles only change Lair settings: no Xdebug process is spawned or stopped.
type DebuggerRequest struct {
	Op string `json:"op"`
}

// DebuggerVersion reports whether an installed PHP line has a usable Xdebug
// module for the debug pool generated by internal/php.
type DebuggerVersion struct {
	Version   string `json:"version"`
	Available bool   `json:"available"`
}

// DebuggerResult is the debugger snapshot returned by every operation.
type DebuggerResult struct {
	Detect      bool              `json:"detect"`
	Breakpoints bool              `json:"breakpoints"`
	Port        int               `json:"port"`
	Mode        string            `json:"mode"`
	Versions    []DebuggerVersion `json:"versions"`
	Domains     []string          `json:"domains"`
}

// DebuggerControl implements the `debugger` daemon action.
func (e *Engine) DebuggerControl(ctx context.Context, req DebuggerRequest) (DebuggerResult, error) {
	var toggle *bool
	switch req.Op {
	case "", "status":
	case "detect-on":
		v := true
		toggle = &v
		// The flag lives on Detect; see update below.
	case "detect-off":
		v := false
		toggle = &v
	case "breakpoints-on":
		v := true
		toggle = &v
	case "breakpoints-off":
		v := false
		toggle = &v
	default:
		return DebuggerResult{}, fmt.Errorf("unknown debugger op %q", req.Op)
	}
	_ = ctx

	if toggle != nil {
		detectToggle := strings.HasPrefix(req.Op, "detect-")
		if err := e.Config.Update(func(c *config.Config) error {
			if c.Debugger.Mode == "" {
				c.Debugger.Mode = "debug"
			}
			if detectToggle {
				c.Debugger.Detect = *toggle
			} else {
				c.Debugger.Breakpoints = *toggle
			}
			return nil
		}); err != nil {
			return DebuggerResult{}, fmt.Errorf("save debugger settings: %w", err)
		}
	}

	c, err := e.Config.View()
	if err != nil {
		return DebuggerResult{}, fmt.Errorf("debugger config: %w", err)
	}
	mode := c.Debugger.Mode
	if mode == "" {
		mode = "debug"
	}

	installed, err := php.Installed(e.Paths)
	if err != nil {
		return DebuggerResult{}, fmt.Errorf("installed PHP: %w", err)
	}
	versions := make([]DebuggerVersion, 0, len(installed))
	for _, info := range installed {
		versions = append(versions, DebuggerVersion{
			Version: info.Minor, Available: xdebugAvailable(info.Dir),
		})
	}
	domains := make([]string, 0, len(c.Sites))
	for name := range c.Sites {
		domains = append(domains, name)
	}
	sort.Strings(domains)
	return DebuggerResult{
		Detect: c.Debugger.Detect, Breakpoints: c.Debugger.Breakpoints,
		Port: config.DefaultDebuggerPort, Mode: mode,
		Versions: versions, Domains: domains,
	}, nil
}

// xdebugAvailable checks the version directory used by php.FPMConfig's debug
// pool (conf.d-xdebug) and the extension directory for an xdebug module.
// Static catalog builds normally ship no loadable module, which yields false.
func xdebugAvailable(dir string) bool {
	found := false
	_ = filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if err != nil || found {
			if err != nil && d != nil && d.IsDir() {
				return fs.SkipDir
			}
			return nil
		}
		if d.IsDir() {
			return nil
		}
		name := strings.ToLower(d.Name())
		if !strings.Contains(name, "xdebug") {
			return nil
		}
		if strings.HasSuffix(name, ".so") || strings.HasSuffix(name, ".dll") {
			found = true
			return fs.SkipAll
		}
		if strings.HasSuffix(name, ".ini") {
			data, err := os.ReadFile(path)
			if err == nil && strings.Contains(string(data), "zend_extension") {
				found = true
				return fs.SkipAll
			}
		}
		return nil
	})
	return found
}
